PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS usuario_Adm (idUsuarioAdm INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,senha TEXT NOT NULL,nome TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','APROVADO','REJEITADO')),dataSolicitacao TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,dataAprovacao TEXT,aprovadoPor INTEGER REFERENCES usuario_Adm(idUsuarioAdm),foto TEXT,criadoEm TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS usuario_Resp (idResp INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,senha TEXT NOT NULL,nome TEXT NOT NULL,cpf TEXT,telefone TEXT,foto TEXT,criadoEm TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS usuario_Aluno (idAluno INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,senha TEXT NOT NULL,nome TEXT NOT NULL,turma TEXT NOT NULL,foto TEXT,criadoEm TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS aluno_respo (idAluno INTEGER NOT NULL REFERENCES usuario_Aluno(idAluno) ON DELETE CASCADE,idResp INTEGER NOT NULL REFERENCES usuario_Resp(idResp) ON DELETE CASCADE,PRIMARY KEY(idAluno,idResp));
CREATE TABLE IF NOT EXISTS conta_Aluno (idConta INTEGER PRIMARY KEY AUTOINCREMENT,idAluno INTEGER NOT NULL UNIQUE REFERENCES usuario_Aluno(idAluno) ON DELETE CASCADE,saldo REAL NOT NULL DEFAULT 0,limiteNegativo REAL NOT NULL DEFAULT 250,limiteDiario REAL NOT NULL DEFAULT 25);
CREATE TABLE IF NOT EXISTS movimento_Conta (idMovi INTEGER PRIMARY KEY AUTOINCREMENT,idConta INTEGER NOT NULL REFERENCES conta_Aluno(idConta) ON DELETE CASCADE,tipo TEXT NOT NULL CHECK(tipo IN ('DEPOSITO','COMPRA','AJUSTE','ESTORNO')),valor REAL NOT NULL,descricao TEXT,dataHora TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS produto (idProd INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,descricao TEXT,categoria TEXT NOT NULL DEFAULT 'Outros',preco REAL NOT NULL,disponivel TEXT NOT NULL DEFAULT 'S' CHECK(disponivel IN ('S','N')),imagem TEXT,criadoEm TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS estoque (idItem INTEGER PRIMARY KEY AUTOINCREMENT,idProd INTEGER NOT NULL UNIQUE REFERENCES produto(idProd) ON DELETE CASCADE,quantidade REAL NOT NULL DEFAULT 0,estoqueMinimo REAL NOT NULL DEFAULT 5);
CREATE TABLE IF NOT EXISTS cardapio (idCard INTEGER PRIMARY KEY AUTOINCREMENT,dataCardapio TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS item_Cardapio (idItemCard INTEGER PRIMARY KEY AUTOINCREMENT,idCard INTEGER NOT NULL REFERENCES cardapio(idCard) ON DELETE CASCADE,idProd INTEGER NOT NULL REFERENCES produto(idProd) ON DELETE CASCADE,disponivel TEXT NOT NULL DEFAULT 'S',UNIQUE(idCard,idProd));
CREATE TABLE IF NOT EXISTS intervalo (idIntervalo INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,horarioInicio TEXT NOT NULL,horarioFim TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pedido (idPedido INTEGER PRIMARY KEY AUTOINCREMENT,idIntervalo INTEGER REFERENCES intervalo(idIntervalo) ON DELETE SET NULL,idAluno INTEGER NOT NULL REFERENCES usuario_Aluno(idAluno),dataHoraPedido TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','PREPARANDO','PRONTO','RETIRADO','CANCELADO')),retirado TEXT NOT NULL DEFAULT 'N' CHECK(retirado IN ('S','N')),tipoVenda TEXT NOT NULL DEFAULT 'ANTECIPADA' CHECK(tipoVenda IN ('ANTECIPADA','BALCAO')),codigoRetirada TEXT UNIQUE,valorTotal REAL NOT NULL);
CREATE TABLE IF NOT EXISTS item_Pedido (idItemPedido INTEGER PRIMARY KEY AUTOINCREMENT,idPedido INTEGER NOT NULL REFERENCES pedido(idPedido) ON DELETE CASCADE,idProd INTEGER NOT NULL REFERENCES produto(idProd),quantidade INTEGER NOT NULL DEFAULT 1,precoUnitario REAL NOT NULL);
